class Solution {
public:
    int countDigitOne(int n) {
        if(n<=0)
            return 0;
        if(n<=9)
            return 1;
        unordered_map<int,int> mp;
        mp[9]=1;
        for(int i=9;i<(INT_MAX-9)/10;i=i*10+9)
            mp[i*10+9]=mp[i]*10+(i+1);
        int divisor=1;
        int temp=n;
        while(temp/10)
        {
            temp/=10;
            divisor*=10;
        }
        int fd=n/divisor;
        int rem=n%divisor;
        int ans=0;
        ans+=fd*mp[divisor-1];
        ans+=(fd>1)?divisor:0;
        ans+=(fd==1)?rem+1:0;
        ans+=countDigitOne(rem);
        return ans;
    }
};

class Solution(object):
    def countDigitOne(self, n):
        """
        :type n: int
        :rtype: int
        """
        if n<0: return 0
        def getNum(m):
            if m==0:
                return 0
            if m==1:
                return 1
            return getNum(m-1)*10+10**(m-1)
        k=1
        result = 0
        part = 0
        while n:
            m = n%10
            result += m*getNum(k-1)
            if m==1:
                result += part+1 
            elif m>1:
                result += 10**(k-1)
            part = part+m*(10**(k-1))
            n = n/10
            k+=1
        return result
